(function(){
'use strict';
const KEY='daydream.tutorial.dismissed.v2',duration=7000;
const cursor='<svg class="demo-cursor" viewBox="0 0 24 30"><path d="M3 2v22l6-6 5 10 4-2-5-10h8Z"/></svg>';
const world='<div class="demo-node"><small>ALTERNATIVE REALITY <span class="demo-pencil">✎</span></small><strong>Wonderland</strong></div>';
const slides=[
 {title:'Create a world.',text:'Click Create a reality. Name your world and confirm.',demo:'create',visual:'<span class="demo-action">+ Create a reality</span><div class="demo-modal"><small>Name</small><span class="demo-input"><b class="demo-typed">Wonderland</b></span><span class="demo-confirm">Confirm</span></div>'},
 {title:'Enter your world.',text:'Click its node to enter. The pencil edits its details.',demo:'enter',visual:world+'<div class="demo-entered"><span class="demo-action">+ Add section</span>'+world+'</div>'},
 {title:'Add a section.',text:'Choose Chapters, Characters, or another section from Add section.',demo:'section',visual:'<span class="demo-action">+ Add section</span><div class="demo-modal"><small>Section</small><div class="demo-options"><span>Chapters</span><span class="demo-choice">Characters</span><span>Locations</span></div><span class="demo-confirm">Confirm</span></div><div class="demo-result demo-node"><small>SECTION</small><strong>Characters</strong></div>'},
 {title:'Connect your nodes.',text:'Drag between connection points. Drag a heading to move a node.',demo:'connect',visual:'<div class="demo-link-source demo-node"><strong>Chapters</strong><i class="demo-port"></i></div><svg class="demo-wire" viewBox="0 0 400 300" preserveAspectRatio="none"><path d="M162 128 C215 128 215 188 265 188"/></svg><div class="demo-link-target demo-node"><i class="demo-port"></i><strong>Characters</strong></div>'},
 {title:'Save a quick thought.',text:'Use Dream Capture. Save a thought, then choose its world and section.',demo:'capture',visual:'<div class="demo-sheet"><small>DREAM CAPTURE</small><div class="demo-writing"><span class="demo-typed">A door in the garden.</span></div><span class="demo-save demo-confirm">Save</span></div><div class="demo-assignment"><span>Wonderland</span><span>Locations</span><span class="demo-confirm">Assign</span></div>'},
 {title:'Open a blank page.',text:'Open a section, then Add character or its matching action. Writing saves as you go.',demo:'write',visual:'<div class="demo-library"><strong>Characters</strong><span class="demo-action">+ Add character</span></div><div class="demo-sheet"><small>Untitled Character</small><strong class="demo-typed">Alice</strong><div class="demo-page-lines"><i></i><i></i><i></i></div></div>'},
 {title:'Bring it together.',text:'Open World Manuscript to collect your saved writing. Choose PDF or JPG to export.',demo:'manuscript',visual:'<div class="demo-manuscript-node demo-node"><small>YOUR SAVED WRITING</small><strong>World Manuscript</strong></div><div class="demo-manuscript-sheet demo-sheet"><small>WORLD MANUSCRIPT</small><strong>Wonderland</strong><div class="demo-manuscript-headings"><b>Chapters</b><span>Down the rabbit hole</span><b>Characters</b><span>Alice</span></div><span class="demo-export-action demo-confirm">Export</span></div><div class="demo-export-menu"><span>PDF</span><span>JPG</span></div>'}
];
const dialog=document.createElement('dialog');dialog.className='tutorial-dialog';dialog.setAttribute('aria-labelledby','tutorial-title');dialog.setAttribute('aria-describedby','tutorial-copy');
dialog.innerHTML='<div class="tutorial-top"><span>QUICK START</span><button data-tour="close" aria-label="Close tutorial">×</button></div><div class="tutorial-layout"><div class="tutorial-visual" aria-hidden="true"></div><div class="tutorial-content"><span id="tutorial-step"></span><h2 id="tutorial-title"></h2><p id="tutorial-copy"></p></div></div><div class="tutorial-controls"><button data-tour="previous">Previous</button><button data-tour="pause">Pause</button><button data-tour="next">Next</button><button data-tour="finish">Open workspace</button></div><div class="tutorial-progress" aria-hidden="true"><span></span></div>';
document.body.append(dialog);
let index=0,elapsed=0,last=null,frame=0,paused=false,opener=null,destination=null,seen=new Set();
const reduced=window.matchMedia('(prefers-reduced-motion: reduce)');
function dismissed(){const uid=window.DaydreamAuth?.user?.uid||'guest';if(seen.has(uid))return true;if(window.DaydreamAuth)return !!window.DaydreamAuth.profile?.tutorialComplete;try{return localStorage.getItem(KEY)==='true';}catch{return false;}}
function finish(){seen.add(window.DaydreamAuth?.user?.uid||'guest');if(window.DaydreamAuth?.user)window.DaydreamAuth.completeTutorial();else if(!window.DaydreamAuth)try{localStorage.setItem(KEY,'true');}catch{}const next=destination;destination=null;dialog.close();if(next&&location.hash!==next)location.hash=next;else window.dispatchEvent(new Event('daydream:tutorial-complete'));}
function render(){const s=slides[index],visual=dialog.querySelector('.tutorial-visual');visual.dataset.demo=s.demo;visual.innerHTML='<div class="tutorial-demo-stage">'+s.visual+cursor+'</div>';dialog.querySelector('#tutorial-title').textContent=s.title;dialog.querySelector('#tutorial-copy').textContent=s.text;dialog.querySelector('#tutorial-step').textContent=`${index+1} / ${slides.length}`;dialog.querySelector('[data-tour=previous]').disabled=false;dialog.querySelector('[data-tour=next]').textContent='Next';dialog.querySelector('[data-tour=pause]').hidden=false;elapsed=0;last=null;paint();updatePause();}
function updatePause(){const b=dialog.querySelector('[data-tour=pause]');b.textContent=paused?'Resume':'Pause';b.setAttribute('aria-pressed',String(paused));b.disabled=reduced.matches;b.title=reduced.matches?'Automatic slides are off for reduced motion':'';dialog.classList.toggle('demo-paused',paused||document.hidden||reduced.matches);}
function paint(){dialog.querySelector('.tutorial-progress span').style.transform=`scaleX(${elapsed/duration})`;}
function tick(time){if(!dialog.open)return;const active=!paused&&!reduced.matches&&!document.hidden;if(active&&last!==null)elapsed+=time-last;last=active?time:null;if(elapsed>=duration){index=(index+1)%slides.length;render();}else paint();frame=requestAnimationFrame(tick);}
function open(options={}){if(dialog.open)return;destination=options.destination||null;opener=document.activeElement;index=0;elapsed=0;paused=reduced.matches;render();dialog.showModal();dialog.querySelector('[data-tour=close]').focus();frame=requestAnimationFrame(tick);}
dialog.addEventListener('click',e=>{const action=e.target.closest('[data-tour]')?.dataset.tour;if(action==='close'||action==='finish'){finish();if(action==='finish'&&window.DaydreamAuth&&!window.DaydreamAuth.user)window.DaydreamAuth.require('#workspace');}if(action==='previous'){index=(index-1+slides.length)%slides.length;render();}if(action==='next'){index=(index+1)%slides.length;render();}if(action==='pause'){paused=!paused;last=null;updatePause();}});
dialog.addEventListener('cancel',e=>{e.preventDefault();finish();});
dialog.addEventListener('close',()=>{cancelAnimationFrame(frame);last=null;if(opener?.isConnected)opener.focus({preventScroll:true});});
dialog.addEventListener('keydown',e=>{if(e.key!=='Tab')return;const nodes=[...dialog.querySelectorAll('button')].filter(n=>!n.hidden&&!n.disabled);const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}});
document.addEventListener('visibilitychange',()=>{last=null;updatePause();});
reduced.addEventListener?.('change',()=>{if(reduced.matches)paused=true;last=null;updatePause();});
document.addEventListener('click',e=>{if(e.target.closest('[data-tutorial-open]'))open();});
window.DaydreamTutorial={open,close(){destination=null;dialog.close();},needsIntro:()=>!dismissed(),enter(options={}){if(!dismissed())open(options);}};
})();
